BEGIN;
CREATE TABLE affiliate.campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, provider_id uuid REFERENCES core.providers(id), external_id text, name text NOT NULL, status core.record_status NOT NULL DEFAULT 'ACTIVE', currency char(3) NOT NULL, rules jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(tenant_id,provider_id,external_id));
CREATE TABLE affiliate.offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, campaign_id uuid REFERENCES affiliate.campaigns(id) ON DELETE CASCADE, external_id text, title text NOT NULL, destination_url text NOT NULL, incentive_allowed boolean NOT NULL DEFAULT false, payout numeric(20,8) CHECK (payout IS NULL OR payout>=0), currency char(3), status core.record_status NOT NULL DEFAULT 'ACTIVE', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(tenant_id,campaign_id,external_id));
CREATE TABLE affiliate.creatives (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, offer_id uuid NOT NULL REFERENCES affiliate.offers(id) ON DELETE CASCADE, kind text NOT NULL, uri text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
COMMIT;
